package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.Instant;
import java.util.*;

public final class ModelSourceService {
    private final Db db;private final ModelDiscoveryService discovery;
    public ModelSourceService(Db db){this(db,new ModelDiscoveryService());}
    public ModelSourceService(Db db,ModelDiscoveryService discovery){this.db=db;this.discovery=discovery;}
    public List<ObjectNode> list(){return db.query("SELECT * FROM model_sources ORDER BY \"createdAt\" ASC").stream().map(ModelSourceService::projection).toList();}
    public static ObjectNode parseModelSource(JsonNode raw){ObjectNode n=RuntimeConnectionService.object(raw,"source",Set.of("sourceId","kind","displayName","baseUrl","credentialEnvRef","status","reasonCode","createdAt","updatedAt","lastTestedAt","lastCatalogRefreshAt","modelCount"));String id=RuntimeConnectionService.bounded(n.get("sourceId"),"sourceId",128);if(!id.matches("[A-Za-z0-9_.:-]+")||!Json.text(n,"kind").equals("openai-compatible"))throw new RuntimeFailure("SOURCE_INVALID","Invalid model source identity");RuntimeConnectionService.bounded(n.get("displayName"),"displayName",255);n.put("baseUrl",ModelDiscoveryService.normalizeModelSourceBaseUrl(Json.text(n,"baseUrl",null)));if(n.has("credentialEnvRef"))RuntimeConnectionService.envName(n.get("credentialEnvRef"));return n;}
    public ObjectNode create(JsonNode input){return db.transaction(tx->create(tx,input));}
    public ObjectNode create(Db tx,JsonNode input){ObjectNode source=parseModelSource(input);String id=Json.text(source,"sourceId");tx.execute("SELECT pg_advisory_xact_lock(hashtext(?))","model-source:"+id);if(tx.exists("SELECT 1 FROM model_sources WHERE \"sourceId\"=?",id))throw new RuntimeFailure("SOURCE_ALREADY_EXISTS","Model source already exists");ObjectNode fields=Json.object("sourceId",id,"kind",source.get("kind"),"displayName",source.get("displayName"),"baseUrl",source.get("baseUrl"),"credentialEnvRef",source.get("credentialEnvRef"),"statusState","UNKNOWN","statusReasonCode","none","modelCount",0);return projection(tx.insert("model_sources",fields));}
    public ObjectNode update(String id,JsonNode patch){return db.transaction(tx->update(tx,id,patch));}
    public ObjectNode update(Db tx,String id,JsonNode patch){ObjectNode current=require(tx,id,true);ObjectNode p=RuntimeConnectionService.object(patch,"patch",Set.of("displayName","baseUrl","credentialEnvRef"));ObjectNode combined=projection(current);combined.setAll(p);ObjectNode parsed=parseModelSource(combined);ObjectNode fields=Json.object("displayName",parsed.get("displayName"),"baseUrl",parsed.get("baseUrl"),"credentialEnvRef",parsed.get("credentialEnvRef"),"statusState","UNKNOWN","statusReasonCode","none","statusTestedAt",null,"updatedAt",Instant.now().toString());return projection(tx.update("model_sources",Json.text(current,"id"),fields));}
    public void delete(String id){db.transaction(tx->{delete(tx,id);return null;});}
    public void delete(Db tx,String id){require(tx,id,true);tx.execute("DELETE FROM model_sources WHERE \"sourceId\"=?",id);}
    public ObjectNode test(String id){return db.transaction(tx->test(tx,id));}
    public ObjectNode test(Db tx,String id){ObjectNode row=require(tx,id,true);try{ObjectNode test=discovery.testOpenAiCompatibleSource(projection(row));return projection(tx.update("model_sources",Json.text(row,"id"),Json.object("statusState",test.get("status"),"statusReasonCode",test.get("reasonCode"),"statusTestedAt",Instant.now().toString(),"modelCount",test.get("modelCount"),"updatedAt",Instant.now().toString())));}catch(RuntimeFailure e){return failed(tx,row,e.code());}}
    public ObjectNode refresh(String id){return db.transaction(tx->refresh(tx,id));}
    public ObjectNode refresh(Db tx,String id){ObjectNode row=require(tx,id,true);try{ObjectNode catalog=discovery.fetchOpenAiCompatibleCatalog(projection(row));ObjectNode source=projection(tx.update("model_sources",Json.text(row,"id"),Json.object("statusState","AVAILABLE","statusReasonCode","none","statusTestedAt",Instant.now().toString(),"lastCatalogRefreshAt",Instant.now().toString(),"modelCount",catalog.path("models").size(),"updatedAt",Instant.now().toString())));return Json.object("source",source,"catalog",catalog);}catch(RuntimeFailure e){return Json.object("source",failed(tx,row,e.code()),"catalog",Json.object("sourceId",id,"discoveredAt",Instant.now().toString(),"models",Json.array()));}}
    private ObjectNode failed(Db tx,ObjectNode row,String reason){return projection(tx.update("model_sources",Json.text(row,"id"),Json.object("statusState",reason.equals("auth-required")?"AUTH_REQUIRED":"UNAVAILABLE","statusReasonCode",reason,"statusTestedAt",Instant.now().toString(),"updatedAt",Instant.now().toString())));}
    private static ObjectNode require(Db tx,String id,boolean lock){ObjectNode row=tx.one("SELECT * FROM model_sources WHERE \"sourceId\"=?"+(lock?" FOR UPDATE":""),id);if(row==null)throw new RuntimeFailure("SOURCE_NOT_FOUND","Model source missing");return row;}
    static ObjectNode projection(JsonNode row){ObjectNode out=Json.object("sourceId",row.get("sourceId"),"kind",row.get("kind"),"displayName",row.get("displayName"),"status",row.get("statusState"),"reasonCode",row.get("statusReasonCode"),"modelCount",row.get("modelCount"),"createdAt",row.get("createdAt"),"updatedAt",row.get("updatedAt"));for(String field:List.of("baseUrl","credentialEnvRef"))if(row.hasNonNull(field))out.set(field,row.get(field));if(row.hasNonNull("statusTestedAt"))out.set("lastTestedAt",row.get("statusTestedAt"));if(row.hasNonNull("lastCatalogRefreshAt"))out.set("lastCatalogRefreshAt",row.get("lastCatalogRefreshAt"));return out;}
}
